use ackplane_client::{ClaimClient, ClientError};

#[tokio::test]
async fn connect_refuses_an_invalid_endpoint_uri() {
    match ClaimClient::connect("not a uri").await {
        Err(ClientError::InvalidEndpoint(endpoint)) => assert_eq!(endpoint, "not a uri"),
        other => panic!(
            "expected InvalidEndpoint, got a different outcome: {}",
            describe(other)
        ),
    }
}

fn describe(result: Result<ClaimClient, ClientError>) -> String {
    match result {
        Ok(_) => "Ok(ClaimClient)".to_string(),
        Err(error) => format!("Err({error})"),
    }
}

#[tokio::test]
async fn probe_reachable_is_false_for_a_closed_local_port() {
    // Port 1 is a reserved/unassigned port that nothing binds to; connecting
    // to it on loopback fails fast (ECONNREFUSED) without needing a real
    // Ackplane deployment, so this arm is deterministic and offline.
    let reachable = ackplane_client::probe_reachable("http://127.0.0.1:1").await;
    assert!(!reachable);
}
